const ASCII = new TextEncoder();
const LATIN1 = LATIN1_EXACT;
const EMPTY_TEXT_SHOW = ASCII.encode("<> Tj");
/** The most bytes one content-stream transaction writes (its MAX_REPLACEMENT_BYTES). */
const MRAI_NATIVE_MAX_REPLACEMENT_BYTES = 64 * 1024;
const NUMBER = "[-+]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)";
const NUMBER_ONLY = new RegExp(`^${NUMBER}$`);
// An empty string `<>` draws nothing and is legal in a TJ array; WeasyPrint
// writes one between two adjustments.
const TJ_ARRAY_ITEM = `(?:<[0-9A-Fa-f\\s]*>|${NUMBER})`;
// A marker is a bullet, a number, one letter or a roman numeral before `.`
// or `)`; a word before `)` ("Agent)") is text.
const LIST_MARKER = /^(?:[•◦▪‣⁃●○■–-]|(?:\d{1,3}|[A-Za-z]|[ivxlcIVXLC]{2,6})[.)])$/u;
/** `Tr` modes whose glyphs are drawn: fill, stroke, fill and stroke. */
const EDITABLE_RENDERING_MODES: ReadonlySet<number> = new Set([0, 1, 2]);
const TJ_SHOW_KINDS: ReadonlySet<string> = new Set(["TJ", "TJ-literal", "TJ-mixed"]);
const PARAGRAPH_FONTS_NOT_ONE_VISUAL_FONT =
  "Paragraph font resources do not describe one visual font.";
/** The largest Tc/Tw a plan records, and replay's bound on every text state a
 * record carries. A content walk reads any finite spacing as written: Word
 * draws a tab's gap as spaces under a Tc and a Tw of a million that cancel on
 * a space, and refusing the value refused every run on that page. */
const MAX_PROVEN_TEXT_SPACING = 100_000;
const MAX_PROVEN_HORIZONTAL_SCALE = 1_000;
// Keep downstream movement inside a tightly bounded text column while
// allowing normal paragraph-after spacing. Three leading intervals cover the
// source line step plus two blank-line equivalents; larger gaps remain an
// independent section/footer boundary and fail closed.
const MAX_PROVEN_PARAGRAPH_GAP_LINES = 3;
// Identity CID fonts have a two-byte code space, including full CJK fonts.
const MAX_NATIVE_CID_COUNT = 0x1_0000;
export const PDF_NATIVE_MAX_TEXT_SELECTION_PROOF_BATCH = 2_048;
