/** Standard 14 fonts draw WinAnsi when the dictionary names it and their
 * built-in StandardEncoding otherwise (PDF 32000-1 §9.6.6). A font whose
 * /Encoding is a dictionary (or names another base encoding) draws the
 * encoding that dictionary builds -- a base encoding with its /Differences
 * applied -- which only the font itself says, so that kind is read from the
 * font rather than from its base font name. */
export type PdfNativeStandard14EncodingKind =
  | "standard14-winansi"
  | "standard14-standard"
  | "standard14-encoded";

export type PdfNativeFontEncodingKind =
  | PdfNativeStandard14EncodingKind
  | "simple-byte"
  | "identity-h-cidfonttype2"
  | "identity-h-cidfonttype0"
  | "identity-v-cidfonttype2"
  | "identity-v-cidfonttype0"
  | PdfNativePredefinedCMapEncodingKind;

/** Type0 fonts encoded through one predefined Unicode UCS-2 CMap. */
export type PdfNativePredefinedCMapEncodingKind =
  | "cmap-h-cidfonttype2"
  | "cmap-h-cidfonttype0"
  | "cmap-v-cidfonttype2"
  | "cmap-v-cidfonttype0";


function isPredefinedCMapEncodingKind(
  kind: PdfNativeFontEncodingKind,
): kind is PdfNativePredefinedCMapEncodingKind {
  return kind.startsWith("cmap-");
}


export type PdfNativeStandard14LatinBaseFont =
  (typeof PDF_NATIVE_STANDARD14_LATIN_BASE_FONTS)[number];

export interface PdfNativeStandard14WinAnsiGlyphAuthority {
  readonly code: number;
  readonly unicodeCodePoint: number;
  readonly character: string;
  readonly glyphName: string;
  readonly width: number;
}

export function isMraiNativeStandard14DisplayAliasCode(code: number): boolean {
  return STANDARD14_DISPLAY_ALIAS_CHARACTERS.has(code);
}



/** The other names a non-embedded font is measured as one of the twelve Latin
 * faces by: the alternative names Acrobat accepts for them (Arial, Times New
 * Roman and Courier New, with `,Bold` `,Italic` `,BoldItalic`), their
 * PostScript spellings, and the faces' own Italic spellings, as pdf.js maps
 * them. Only families drawn to the same widths as the face they name; Arial
 * Narrow and Arial Black are not. Keys are written the way
 * `standard14FaceFor` normalizes a name (mirror of replay). */
const STANDARD14_LATIN_ALIASES: ReadonlyMap<string, PdfNativeStandard14LatinBaseFont> =
  new Map([
    ["Arial", "Helvetica"],
    ["ArialMT", "Helvetica"],
    ["Arial-Bold", "Helvetica-Bold"],
    ["Arial-BoldMT", "Helvetica-Bold"],
    ["Arial-Italic", "Helvetica-Oblique"],
    ["Arial-ItalicMT", "Helvetica-Oblique"],
    ["Arial-BoldItalic", "Helvetica-BoldOblique"],
    ["Arial-BoldItalicMT", "Helvetica-BoldOblique"],
    ["Helvetica-Italic", "Helvetica-Oblique"],
    ["Helvetica-BoldItalic", "Helvetica-BoldOblique"],
    ["TimesNewRoman", "Times-Roman"],
    ["TimesNewRomanPS", "Times-Roman"],
    ["TimesNewRomanPSMT", "Times-Roman"],
    ["TimesNewRoman-Bold", "Times-Bold"],
    ["TimesNewRomanPS-Bold", "Times-Bold"],
    ["TimesNewRomanPS-BoldMT", "Times-Bold"],
    ["TimesNewRoman-Italic", "Times-Italic"],
    ["TimesNewRomanPS-Italic", "Times-Italic"],
    ["TimesNewRomanPS-ItalicMT", "Times-Italic"],
    ["TimesNewRoman-BoldItalic", "Times-BoldItalic"],
    ["TimesNewRomanPS-BoldItalic", "Times-BoldItalic"],
    ["TimesNewRomanPS-BoldItalicMT", "Times-BoldItalic"],
    ["CourierNew", "Courier"],
    ["CourierNewPS", "Courier"],
    ["CourierNewPSMT", "Courier"],
    ["CourierNew-Bold", "Courier-Bold"],
    ["CourierNewPS-BoldMT", "Courier-Bold"],
    ["CourierNew-Italic", "Courier-Oblique"],
    ["CourierNewPS-ItalicMT", "Courier-Oblique"],
    ["CourierNew-BoldItalic", "Courier-BoldOblique"],
    ["CourierNewPS-BoldItalicMT", "Courier-BoldOblique"],
    ["Courier-Italic", "Courier-Oblique"],
    ["Courier-BoldItalic", "Courier-BoldOblique"],
  ]);

/** The Latin Standard 14 face a font dictionary's BaseFont is measured as:
 * the face itself, or a name readers take for it once `,` and `_` read as
 * `-` and spaces are dropped (`Arial,Bold` is Helvetica-Bold). Null for any
 * other font. */
function standard14FaceFor(baseFont: string): PdfNativeStandard14LatinBaseFont | null {
  if (isStandard14LatinBaseFont(baseFont)) return baseFont;
  const normalized = baseFont.replace(/[,_]/g, "-").replace(/\s/g, "");
  if (isStandard14LatinBaseFont(normalized)) return normalized;
  return STANDARD14_LATIN_ALIASES.get(normalized) ?? null;
}




export type PdfNativeFontEncoding = Readonly<
  | {
      kind: PdfNativeStandard14EncodingKind;
      codeUnitBytes: 1;
      baseFont: PdfNativeStandard14LatinBaseFont;
    }
  | {
      kind: "simple-byte";
      codeUnitBytes: 1;
    }
  | {
      kind:
        | "identity-h-cidfonttype2"
        | "identity-h-cidfonttype0"
        | "identity-v-cidfonttype2"
        | "identity-v-cidfonttype0";
      codeUnitBytes: 2;
    }
  | {
      kind: PdfNativePredefinedCMapEncodingKind;
      codeUnitBytes: 2;
      /** Exact predefined CMap name the Type0 /Encoding entry declares. */
      cmapName: string;
    }
>;

export interface PdfNativeListTextReplacementInput {
  readonly sourceBytes: Uint8Array;
  readonly target: PdfNativeIndirectObjectRef;
  readonly font: PdfNativeListFontAuthority;
  readonly additionalFonts?: readonly PdfNativeListFontAuthority[];
  /**
   * Source-derived fonts which are decoded only to prove untouched adjacent
   * layout. They never become editable resources or property choices.
   */
  readonly layoutWitnessFonts?: readonly PdfNativeListFontAuthority[];
  readonly originalText: string;
  readonly replacementText: string;
  readonly selectionItems?: readonly PdfNativeListTextSelectionItemEvidence[];
  /** Planned as one run of a positioned group or frame: its span has to
   * stay the show, so the line's later runs are never moved here. */
  readonly leafOfGroup?: boolean;
  /** Spans of a Qt fake-bold overprint pass the group writing this run
   * already takes the edit into (its duplicate of the run's text object):
   * their shows are the run's own copy, not another text under it. */
  readonly ownedOverprintSpans?: readonly Readonly<{ start: number; end: number }>[];
  /** For a run of a positioned group that widens where the group moves the
   * runs after it: the room the group proves past its end, as this run's
   * width (the run's own room ends at the run it abuts). */
  readonly groupRunCapacity?: number;
  /** Planned as one line of a positioned paragraph, edited where it stands:
   * the lines after it on its visual line stay where they are, so the gap
   * before the next show is read as for a show edited on its own. */
  readonly readsNextShow?: boolean;
  /** A writer proof that would rather move the line's later runs than fit
   * into the free space beside the show, when that leaves more room. */
  readonly preferLineShift?: boolean;
  /** A paragraph-properties text plan: replay proves its record with the
   * source proof, which takes a frame whose runs are drawn in several
   * colours (mirror of replay's allow_mixed_color_source_proof). */
  readonly allowMixedColorFrame?: boolean;
}

