// the stream into a buffer of its own, and a page set in 121 faces read the
// same bytes 300 times over before the readings were shared by content.
const textEventReadings = new Map<string, Map<string, readonly TextEvent[]>>();
/** What each text object of a stream gives a reading, whichever objects the
 * reading leaves out (see readTextEvents' blockReadings). */
type TextBlockReading = Readonly<{ events: readonly TextEvent[] } | { refusal: unknown }>;
const TEXT_BLOCK_BEING_WALKED: TextBlockReading = Object.freeze({ events: Object.freeze([]) });
